def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split pre-release
        if '-' in v:
            main, prerelease = v.split('-', 1)
        else:
            main = v
            prerelease = None

        # Parse main version
        parts = main.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease is not None:
            identifiers = prerelease.split('.')
            prerelease_parsed = []
            for ident in identifiers:
                if ident.isdigit():
                    prerelease_parsed.append((0, int(ident)))
                else:
                    prerelease_parsed.append((1, ident))
        else:
            prerelease_parsed = None

        return (major, minor, patch, prerelease_parsed)

    def compare_key(v):
        major, minor, patch, prerelease_parsed = parse_version(v)

        # Create sort key: (major, minor, patch, has_prerelease, prerelease_identifiers)
        # has_prerelease: 0 if has prerelease (sorts first), 1 if no prerelease (sorts later)
        if prerelease_parsed is None:
            return (major, minor, patch, 1, [])
        else:
            return (major, minor, patch, 0, prerelease_parsed)

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=compare_key)

